<?php
// ===============================================
// ARQUIVO: 5c_escalas/pages/regras.php
// Regras do 5C Escalas para ver e imprimir: estrutura, alocação, restrições (dos OM e das páginas),
// liderança, pedidos, páginas, pessoas, KPI e a política de páginas. Os números vêm dos Parâmetros (o que vale
// agora). O texto fica em PT e EN lado a lado (como o Glossário); impresso no papel timbrado.
// ===============================================

$par = [];
foreach (escQ('SELECT chave, valor FROM ' . escT('esc_parametro')) as $l) {
    $par[$l['chave']] = (string) $l['valor'];
}
$v = static fn(string $k, string $padrao) => $par[$k] ?? $padrao;
$pol = escPolParam();
$pct = static fn($x) => num((float) $x * 100, 0) . '%';
$prazos = [];
foreach ([0.50, 0.60, 0.70, 0.80] as $a) {
    $prazos[] = $pct($a) . ' → ' . escPolPrazo($a, $pol) . 'd';
}
$prio = [];
if (escPolInstalada() && escPodeVerRestrito()) {
    $nomes = escNomes();
    foreach (escQ('SELECT pagina, rep_codes, motivo FROM ' . escT('esc_pagina_prioridade') . ' WHERE vigente_ate IS NULL ORDER BY pagina') as $l) {
        $prio[] = $l['pagina'] . ': ' . implode(', ', array_map(static fn($r) => nomeCurto($nomes[trim($r)] ?? trim($r)), explode(',', strtoupper((string) $l['rep_codes'])))) . ($l['motivo'] ? ' (' . $l['motivo'] . ')' : '');
    }
}
$x = [
    '{virada}' => dataBr(substr($v('v4_virada', '2026-10-31 21:00'), 0, 10)) . ' ' . substr($v('v4_virada', '2026-10-31 21:00'), 11, 5),
    '{h12}' => $v('v4_horas_seguidas_max', '12'), '{h52}' => $v('v4_horas_semana_max', '52'), '{fator}' => str_replace('.', ',', $v('v4_fator_pessoas_posto', '1.5')),
    '{limite}' => $v('limite_fans_rep', '35'), '{over}' => $pct($v('v4_over_capacity_max', '0.30')), '{antec}' => $v('indisp_antecedencia_h', '72'),
    '{meses}' => $v('indisp_recorrente_max_meses', '3'), '{janela_m}' => $v('merito_janela_dias', '28'), '{meia}' => $v('merito_infracao_meia_vida_dias', '90'),
    '{piso}' => $pct($pol['pol_piso']), '{corte}' => $pct($pol['pol_corte_acomp']), '{pmin}' => (int) $pol['pol_prazo_min'], '{pmax}' => (int) $pol['pol_prazo_max'],
    '{gamma}' => str_replace('.', ',', (string) $pol['pol_gamma']), '{acomp}' => (int) $pol['pol_prazo_acomp'], '{dest}' => $pct($pol['pol_destaque']), '{destd}' => (int) $pol['pol_destaque_dias'],
    '{car}' => (int) $pol['pol_carencia'], '{omin}' => (int) $pol['pol_owner_min'], '{maxs}' => (int) $pol['pol_max_trocas_semana'], '{jan}' => (int) $pol['pol_janela'], '{dmin}' => (int) $pol['pol_dias_minimos'],
    '{meta_min}' => $pct($v('v4_melhores_meta_min', '0.65')), '{acima}' => $v('merito_pts_faixa_acima', '8'), '{abaixo}' => str_replace('-', '−', $v('merito_pts_faixa_abaixo', '-8')),
    '{trn_min}' => $pct($v('treinamento_ating_min', '0.85')),
    '{base_fatia}' => (string) round((float) str_replace(',', '.', $v('v4_base_min_fatia', '0.25')) * 100), '{base_mov}' => (string) round((float) str_replace(',', '.', $v('v4_base_mov_max', '0.20')) * 100),
    '{teto_turno}' => (string) (int) (escQ1("SELECT valor FROM `5c_planning`.`fc_parametros` WHERE chave = 'teto_turma_turno'")['valor'] ?? 10), '{blocos_sr}' => (string) ESC_DST_BLOCOS_SR,
    '{bf_max}' => str_replace('.', ',', $v('v4_baixo_fluxo_max', '12')), '{bloq}' => $v('v4_saida_bloqueio_dias', '60'),
    '{so_br}' => implode(', ', array_filter(array_map('trim', explode(',', $v('v4_plataforma_so_brasil', 'Privacy'))))) ?: '—',
    '{plat_pt}' => $v('v4_uma_plataforma_turno', '1') !== '0' ? 'ligada hoje' : 'desligada hoje',
    '{plat_en}' => $v('v4_uma_plataforma_turno', '1') !== '0' ? 'on today' : 'off today',
    '{prazos}' => implode(' · ', $prazos), '{prio}' => $prio ? implode('; ', $prio) : '—',
];
$en = escEmIngles();
$R = [
    'estrutura' => ['Estrutura da operação', 'Operation structure', [
        ['3 unidades (U1, U2, U3). Cada unidade tem os 3 turnos: T6/T1 (21:00–05:00), T2/T3 (05:00–13:00) e T4/T5 (13:00–21:00).', '3 units (U1, U2, U3). Each unit has the 3 shifts: T6/T1 (21:00–05:00), T2/T3 (05:00–13:00) and T4/T5 (13:00–21:00).'],
        ['Cada unidade e turno tem 3 núcleos, cada um com um Operational Supervisor (OS) e os seus SRs. Rotação 5x2 de 21 dias: todo dia 2 dos 3 núcleos trabalham.', 'Each unit and shift has 3 cores, each with an Operational Supervisor (OS) and its SRs. 21-day 5x2 rotation: every day 2 of the 3 cores work.'],
        ['Cargos: Operational Unit Manager (OM, por unidade), Operational Coordinator (OC, por unidade e turno), Operational Supervisor (OS, por núcleo), Operational Assistant (OA, assistentes dos OMs, semana fixa) e Sales Representative (SR, níveis 0 a 5).', 'Roles: Operational Unit Manager (OM, per unit), Operational Coordinator (OC, per unit and shift), Operational Supervisor (OS, per core), Operational Assistant (OA, assistants to the OMs, fixed week) and Sales Representative (SR, levels 0 to 5).'],
        ['A estrutura nova vale a partir de {virada}. O roster da liderança muda em Pessoas › Roster da liderança, sempre a partir de uma data.', 'The new structure applies from {virada}. The leadership roster changes in People › Leadership roster, always from a date.'],
    ]],
    'alocacao' => ['Alocação: como a escala é montada', 'Allocation: how the schedule is built', [
        ['As páginas ficam na carteira de uma unidade (Capacity). Cada página tem posto(s) por turno, com {limite} fãs/h por posto; o Capacity calcula {fator} SRs por posto.', 'Pages sit in a unit portfolio (Capacity). Each page has post(s) per shift, with {limite} fans/h per post; Capacity counts {fator} SRs per post.'],
        ['Cada posto tem um núcleo dono (vaga de dono: os owners) e um núcleo de cobertura (vaga de cobertura: os backups), que cobre nos dias de folga do dono.', 'Each post has an owning core (owner slot: the owners) and a covering core (cover slot: the backups), which covers on the owner\'s days off.'],
        ['A página segue o SR (desde 26/11): ao publicar uma versão da escala, o posto passa para o núcleo do SR que mais faz a página como titular na semana (com ao menos 40% das células e mais que o núcleo de hoje); a cobertura vai para o núcleo de antes. Cada OS tem um grupo fixo de SRs: quem desenvolve os melhores SRs fica com as melhores páginas. Quando o Capacity refaz o posto (uma página entra ou sai dele), o posto novo fica no núcleo do anterior; página que saiu e voltou volta para a carteira e o núcleo de antes.', 'A page follows the SR (since Nov 26): when a schedule version is published, the post moves to the core of the SR who works the page most as owner that week (with at least 40% of the cells and more than today\'s core); the cover goes to the previous core. Each OS has a fixed group of SRs: whoever develops the best SRs gets the best pages. When Capacity rebuilds a post (a page joins or leaves it), the new post stays in the previous one\'s core; a page that left and came back returns to its previous portfolio and core.'],
        ['Agências parceiras ficam numa unidade à parte, fora da escala, do Capacity e do equilíbrio (só informativo): U4 Vencel e U5 Majstore.', 'Partner agencies sit in a unit of their own, outside the schedule, Capacity and balance (for information only): U4 Vencel and U5 Majstore.'],
        ['Os postos seguem o Capacity de hoje: antes de gerar ele é sempre recalculado (etapa 2 do Gerar em etapas; antes vem a verificação, que para em saída de página a conferir), página ativa com movimento que faltava entra sozinha (arquétipo de página parecida) e página sem posto num turno vira apoio no posto da mesma modelo.', 'Posts follow today\'s Capacity: it is always recalculated before generating (step 2 of Generate in steps; first comes the check, which stops on a page exit still to check), an active page with activity that was missing is added automatically (archetype of a similar page) and a page with no post on a shift becomes support in the same model\'s post.'],
        ['Prioridade é faturamento: os postos são preenchidos da modelo que mais fatura para a que menos fatura, e as páginas da mesma modelo (VIP, Free, OFTV) contam como uma só, para não falhar na Free ou na secundária. Vale o faturamento dos últimos 30 dias, com as vendas fechadas e as pendentes; página com menos dias de venda tem a média emulada para 30 dias e, sem venda nenhuma, vale o meio da faixa do tier.', 'Revenue comes first: posts are filled from the model with the highest revenue to the lowest, and pages of the same model (VIP, Free, OFTV) count as one, so the Free or secondary page is not dropped. Revenue is the last 30 days, with completed and pending sales; a page with fewer days of sales has its average projected to 30 days and, with no sales at all, the middle of its tier range is used.'],
        ['Melhor SR, de cima para baixo: depois da equipe fixa da página, cada página, da modelo que mais fatura para a que menos fatura, escolhe o melhor SR disponível na unidade e no turno. Primeiro quem bateu {meta_min} ou mais da meta na modelo da página (todas as páginas dela) em 30 dias; depois o nível do KPI (4 a 0), o score e o tempo de casa (ter feito a página sem bater {meta_min} não conta). Quem estava no posto fica, a não ser que apareça um SR de nível que o tire ou que ele esteja abaixo de {meta_min} da meta na modelo. O SR de nível 0 do KPI não entra como regular numa página de modelo de US$ 100 mil ou mais (prioritária) enquanto houver outro disponível na unidade e no turno; sem outro, entra sinalizado. As páginas prioritárias escolhem antes da base da semana anterior das outras, mas não tiram da base quem é da página vermelha. O posto de assistente continua só para SR 0 a 2.', 'Best SR, top to bottom: after the page\'s fixed team, each page, from the highest-revenue model to the lowest, picks the best SR available in the unit and shift. First whoever hit {meta_min} or more of the target on the page\'s model (all its pages) in 30 days; then the KPI level (4 to 0), the score and tenure (having worked the page without hitting {meta_min} does not count). Whoever was on the post stays, unless an SR at a level that displaces them shows up or they are below {meta_min} of the model target. A KPI level 0 SR does not go in as regular on a page of a US$ 100k+ model (priority) while someone else is available in the unit and shift; with no one else, they go in flagged. Priority pages pick before the previous-week baseline of the other pages, but do not take from the baseline someone who is on a red page. The assistant post is still only for SR 0 to 2.'],
        ['Experiência e meta contam pela modelo, não pela página: conhecer uma das páginas da modelo basta (ex.: Mikayla Free ou Mikayla Paid). Os dias são os dias distintos em qualquer página da modelo (o mesmo dia em duas páginas conta uma vez) e a meta soma o realizado e a meta de todas as páginas dela. Vale para quem conhece a página vermelha ou amarela (P-02), para quem bateu a meta no melhor SR, para a continuidade no posto e para as tags Exp., Inexp., Meta ✓ e Meta ✗. A venda por hora continua por página.', 'Experience and target count by model, not by page: knowing one of the model\'s pages is enough (e.g. Mikayla Free or Mikayla Paid). Days are the distinct days on any page of the model (the same day on two pages counts once) and the target adds up the result and target of all its pages. It applies to who knows a red or yellow page (P-02), to who hit the target in the best SR, to staying on the post and to the Exp., Inexp., Goal ✓ and Goal ✗ tags. Sales per hour is still per page.'],
        ['Página desconsiderada (Páginas › Configuração das páginas): sem SLA a cumprir, carga zero no posto e última a receber gente; se ela tiver posto próprio, entra de apoio no posto da página principal da mesma modelo, com o mesmo SR. No automático é a OFTV (ou código terminado em t) que faturou menos de US$ 8 mil em 30 dias; acima disso é posto normal. A chave da página pode forçar "Sempre normal" ou "Desconsiderar".', 'Disregarded page (Pages › Page settings): no SLA to meet, zero load in the post and last to get people; if it has its own post, it becomes support in the post of the same model\'s main page, with the same SR. On automatic it is an OFTV page (or a code ending in t) that made less than US$ 8k in 30 days; above that it is a normal post. The page setting can force "Always normal" or "Disregard".'],
        ['Nenhum posto fica sem equipe: antes de gerar, a vaga sem ninguém é completada com SRs do turno (núcleo da vaga, outro núcleo, nível 0–2 acima da fatia e, por último, o menos carregado). Na página prioritária vem primeiro o score do KPI e não entram o nível 0 do KPI nem o new hire; o new hire só entra pela rampa (fora na 1ª semana, Tier F na 2ª, Tier E depois). A vaga que o próprio Gerar completou com quem não cabe mais é refeita.', 'No post is left without a team: before generating, an empty slot is filled with SRs from the shift (the slot\'s core, another core, levels 0–2 above their share and, last, the least loaded). On a priority page the KPI score comes first and neither KPI level 0 nor new hires go in; new hires only go in by the ramp (out in the 1st week, Tier F in the 2nd, Tier E after). A slot that Generate itself filled with someone who no longer fits is redone.'],
        ['O motor preenche cada vaga, por dia, nesta ordem: 1) a equipe fixa da vaga (preferência, não trava); 2) outra pessoa do mesmo núcleo, primeiro quem já atua na página; 3) buffer (pessoa de outro núcleo em serviço no turno); 4) o que sobra vira lacuna. Quem fica sem vaga no dia é o buffer de plantão.', 'The engine fills each slot, per day, in this order: 1) the slot\'s fixed team (a preference, not a lock); 2) someone else from the same core, first those who already work the page; 3) buffer (someone from another core on shift); 4) what is left is a gap. Whoever has no slot that day is the on-call buffer.'],
        ['Regular e assistente na página: em cada página e bloco, o primeiro SR a entrar é o regular (sai sem # no CSV) e os próximos, que ajudam no capacity, são assistentes (#). O papel não diz quem é dono do posto nem quem está cobrindo: uma página de apoio ou coberta por sobrecarga, com uma pessoa só, tem regular.', 'Regular and assistant on the page: on each page and block, the first SR in is the regular (no # in the CSV) and the next ones, who help with capacity, are assistants (#). The role does not say who owns the post or who is covering: a support page or one covered by overload, with a single person, has a regular.'],
        ['Assistente (posto de assistente ou de apoio) é só para SR 0 a 2: SR 3 ou mais nunca entra nessas vagas, nem pela equipe fixa. Se não houver SR 0 a 2 no turno, o posto de assistente fica vazio.', 'Assistant (assistant or support post) is only for SR 0 to 2: SR 3 or above never takes these slots, not even through the fixed team. If there is no SR 0 to 2 on shift, the assistant post stays empty.'],
        ['Modelo de faturamento maior com posto vazio: um SR de uma modelo menor do turno vai para ela, o de melhor nível do KPI (no empate, o da modelo que menos fatura), também nos dias de transição da virada (31/10). Entre páginas da mesma modelo ninguém é tirado, e quem é da equipe fixa de uma página não sai dela.', 'A bigger-revenue model with an empty post: an SR from a smaller model of the shift moves to it, the one with the best KPI level (on a tie, the one from the lowest-revenue model), also on the switch-over transition days (10/31). Nobody is moved between pages of the same model, and whoever is on a page\'s fixed team does not leave it.'],
        ['Limites: até {h12} h seguidas e {h52} h por semana; para fechar lacuna, um SR já alocado pode puxar páginas até {over} acima da capacidade, só da mesma agência das páginas que ele já faz (a do Infloww; Noah, Independent e Lolly Agency contam como 5C Company): entra cobrindo, sem ser dono (não conta para a semana seguinte), e cede a página quando houver gente (⚠ na grade).', 'Limits: up to {h12} h in a row and {h52} h per week; to close a gap, an SR already placed may pull pages up to {over} over capacity, only from the same agency as the pages they already work (the Infloww one; Noah, Independent and Lolly Agency count as 5C Company): they come in covering, not as owner (it does not count for the next week), and give the page up when people are available (⚠ on the grid).'],
        ['Dados históricos (KPI, metas, faltas, SLA, vendas, quem conhece a página, política e tags) contam só a partir de 01/11/2026, mesmo quando a janela é maior. O Capacity não muda, e o Equilíbrio das unidades usa sempre o faturamento dos 30 dias anteriores.', 'Historical data (KPI, goals, absences, SLA, sales, who knows the page, policy and tags) only count from 11/01/2026, even when the window is longer. Capacity does not change, and Unit balance always uses the revenue of the previous 30 days.'],
        ['Ajuste manual na Grade fica travado: o recálculo mantém. Publicar mostra o resumo antes; o que vale para postar no site da 5C é a Grade publicada.', 'Manual adjustments on the Grid stay locked: recalculation keeps them. Publishing shows a summary first; what gets posted on the 5C website is the published Grid.'],
        ['Quem está travado num turno não é usado pelo Gerar em outra célula desse turno, e posto com todas as células travadas não gasta ninguém. Se a versão mudar enquanto o sistema calcula, a geração para com aviso.', 'Whoever is locked in a shift is not used by Generate in another cell of that shift, and a post with all cells locked uses nobody. If the version changes while the system calculates, generation stops with a notice.'],
    ]],
    'base' => ['Base da semana anterior, 80/20 e Anjo', 'Previous week baseline, 80/20 and Angel', [
        ['Desde a 1.37.0 a escala da semana anterior (a publicada; sem ela, a versão atual) é a base: as páginas de cada SR nela (as que tiveram {base_fatia}% ou mais dos blocos dele) valem como verdade, e quem fez a página conta como quem a conhece (página vermelha).', 'Since 1.37.0 the previous week\'s schedule (the published one; without it, the current version) is the baseline: each SR\'s pages in it (those with {base_fatia}% or more of their blocks) are taken as true, and whoever worked the page counts as knowing it (red page).'],
        ['O motor roda uma vez livre e lista as trocas sobre a base. Só {base_mov}% delas acontecem, as de maior impacto: faturamento da página no turno × (score do KPI de quem entra − score de quem sai). Mudança de unidade, turno ou núcleo no cadastro conta nesses {base_mov}% e vem primeiro. Ficam fora da conta, e acontecem sempre: saída da escala, página que saiu ou mudou de unidade ou turno, equipe fixa da página (main, cover, equipe) e célula travada à mão.', 'The engine runs once freely and lists the swaps over the baseline. Only {base_mov}% of them happen, the ones with the biggest impact: page revenue in the shift × (KPI score of who comes in − score of who leaves). A change of unit, shift or core in the records counts in those {base_mov}% and comes first. Left out of the count, and always applied: leaving the schedule, a page that left or changed unit or shift, the page fixed team (main, cover, team) and cells locked by hand.'],
        ['Anjo: cada OS pode escolher 1 SR do núcleo que ia mudar de página por troca do motor, para ficar mais uma semana na página atual. O Planejamento registra em Escala › Movimentações e Anjos, e o Anjo vale no próximo Gerar ou recálculo da semana. Depois o motor roda de novo: quem fica entra na página da base antes do melhor SR (depois da equipe fixa) e não sai dela para remanejar.', 'Angel: each OS can pick 1 SR from the core who was going to change page because of an engine swap, to stay one more week on the current page. Planning records it in Schedule › Moves and Angels, and the Angel applies at the next Generate or recalculation of the week. Then the engine runs again: whoever stays goes on the baseline page before the best SR (after the fixed team) and does not leave it to be moved up.'],
    ]],
    'restricoes' => ['Restrições das páginas e das pessoas', 'Page and people restrictions', [
        ['Os pedidos dos OMs ficam em Páginas › Restrições dos OM, com PDF por unidade para mandar às equipes. Valem na equipe fixa e no preenchimento; não mudam a ordem do melhor SR de cima para baixo. Restrição desativada não vale no Gerar até ser ativada de novo.', 'The OMs\' requests are in Pages › OM restrictions, with a PDF per unit to send to the teams. They apply to the fixed team and to filling; they do not change the order of the best SR top to bottom. A deactivated restriction does not apply in Generate until it is activated again.'],
        ['Equipe fixa da página: entra antes de todos na página, por turno. Primeiro os titulares (main) de todas as páginas, depois quem cobre (cover) e por último o resto da equipe. Entre dois main (ou dois cover) do mesmo turno, fica o que vem antes na lista; o segundo só entra quando o primeiro folga (1.44.0). Main e cover entram mesmo sendo de outra unidade (as páginas da U1 escolhem primeiro, depois U2 e U3) e também no dia de Overlap, que conta como treinamento; a página deles fica liberada de "só estas páginas", tier e faixa de faturamento. O resto da equipe só entra se for da unidade da página; no Overlap, cobre primeiro a lacuna da própria página. É regra do cadastro: vale em qualquer Gerar, até no "Gerar do zero", e o "mínimo de mudanças" não a desfaz.', 'Page fixed team: goes on the page before everyone else, per shift. First the main SRs of all pages, then the covers and last the rest of the team. Between two mains (or two covers) in the same shift, the one listed first stays; the second only comes in when the first is off (1.44.0). Mains and covers come in even from another unit (U1 pages choose first, then U2 and U3) and also on their Overlap day, which counts as training; their page is exempt from "these pages only", tier and revenue range. The rest of the team only comes in if from the page\'s unit; on Overlap, they cover their own page\'s gap first. It is a rule in the records: it holds in every Generate, even "Generate from scratch", and "fewest changes" does not undo it.'],
        ['Divisão do SR (ex.: 50/50): o SR reparte os turnos em que está disponível entre as páginas da lista, na parte de cada uma (só páginas da unidade dele, desde a 1.35.0); o que faltar para 100% é a escala normal da unidade dele. A cada dia a vez é da página mais atrasada na parte dela. A divisão vem antes da equipe fixa, e a equipe fixa não toma a vaga que a divisão deu.', 'SR split (e.g. 50/50): the SR splits the shifts they are available for among the pages on the list, in each one\'s share (only pages of their own unit, since 1.35.0); whatever is missing to 100% is the regular schedule of their unit. Each day the turn goes to the page furthest behind its share. The split comes before the fixed team, and the fixed team does not take the slot the split gave.'],
        ['Assistente: "só assistente" entra só em posto de assistente, de qualquer nível, e não acumula nem cobre página. "Serve como assistente" tem a vez no posto de assistente, em qualquer nível. "Não faz assistente" nunca entra nesse posto. O assistente marcado numa página tem a vez no posto de assistente dela. Proibido na página: a pessoa nunca entra nela.', 'Assistant: "assistant only" only takes assistant posts, at any level, and does not stack or cover pages. "Works as assistant" gets priority for the assistant post, at any level. "Does not work as assistant" never takes that post. The assistant marked on a page gets priority for its assistant post. Banned from the page: the person never goes on it.'],
        ['Baixo fluxo: só posto de até {bf_max} fãs/h ou de assistente; não acumula nem cobre. Baixo fluxo estrito: nunca em posto acima de {bf_max} fãs/h, nem de assistente.', 'Low flow: only posts up to {bf_max} fans/h or assistant posts; no stacking or covering. Strict low flow: never on a post above {bf_max} fans/h, not even as assistant.'],
        ['Só uma página: não fica em posto com mais de uma página (fora as de apoio), não acumula outro posto nem cobre página. Várias páginas ao mesmo tempo: no turno dele, o SR pega todos os postos que só têm páginas da lista, acumulando, sem assistente e sem limite de capacidade. Só estas páginas: nenhuma outra, nem para acumular ou cobrir. Também há tier médio (só páginas de tier C ou D), tier médio ou alto (A a D), faixa de faturamento da página, preferência por página masculina e por certas páginas, e solo (nunca como assistente nem em posto com assistente, com data de fim se o OM pedir). A página da divisão vale sempre para quem divide.', 'One page only: not put on a post with more than one page (support pages aside), no stacking another post and no covering. Several pages at once: in their shift, the SR takes every post that only has pages from the list, stacking them, with no assistant and no capacity limit. These pages only: no other page, not even to stack or cover. There are also mid tier (only tier C or D pages), mid or high tier (A to D), page revenue range, preference for male pages and for certain pages, and solo (never as assistant nor on a post with an assistant, with an end date if the OM asks). The split page always applies to the person splitting.'],
        ['Uma plataforma por turno ({plat_pt}): quem faz Privacy, Fanvue ou PlayBoy não acumula nem cobre página de outra plataforma no mesmo turno, e o contrário também vale. Vale no Gerar e no Recalcular com o mínimo de mudanças, que tira a mistura da versão publicada (fica a página da Privacy, Fanvue ou PlayBoy).', 'One platform per shift ({plat_en}): whoever works Privacy, Fanvue or PlayBoy does not stack or cover a page of another platform in the same shift, and the reverse also holds. It applies to Generate and to Recalc With Minimum Changes, which removes a mix from the published version (the Privacy, Fanvue or PlayBoy page stays).'],
        ['Só SR brasileiro nas páginas de: {so_br}. A nacionalidade vem do cadastro de pessoas; nunca se fixa estrangeiro nelas.', 'Brazilian SRs only on the pages of: {so_br}. Nationality comes from the people records; a foreign SR is never fixed on them.'],
        ['Alocação da página: Active team (padrão) recebe gente pelo Gerar. On demand: o Gerar não põe ninguém; quando pedem, a alocação é feita à mão na Grade, com a célula travada. Exclusiva (solo): o SR da página não acumula nem cobre outra página; ela só tem assistente quando o posto é de 2 pessoas.', 'Page allocation: Active team (default) gets people through Generate. On demand: Generate puts no one on it; when asked, the allocation is done by hand on the Grid, with the cell locked. Exclusive (solo): the page\'s SR does not stack or cover another page; it only has an assistant when the post is for 2 people.'],
        ['Página que saiu pela tela Saídas de página não volta sozinha por {bloq} dias, mesmo ativa no site. Quando fica ativa de novo, aparece no Funil de entrada (Ativas no site, fora da escala), e o Gerar avisa: ali ela é posta na escala (com o núcleo escolhido, se a página não divide o posto com outra sem núcleo) ou ignorada. As outras páginas ativas sem carteira entram sozinhas no Gerar quando têm escala no site ou venda.', 'A page that left through the Page exits screen does not come back by itself for {bloq} days, even if active on the website. When it becomes active again, it shows up in the Intake funnel (Active on the website, outside the schedule), and Generate warns about it: there it is put in the schedule (in the chosen core, unless the page shares the position with another page without one) or ignored. Other active pages without a portfolio join by themselves at Generate when they have a schedule on the website or sales.'],
        ['Quem é desligado e página que sai perdem as restrições sozinhos, no último dia: a pessoa sai da equipe fixa (o resto da equipe continua), fecham o só assistente, o proibido e a divisão, e as listas perdem quem saiu e a página que saiu. Roda no fim da saída de página e antes de cada Gerar. Quem passou para a liderança não conta como desligado.', 'Whoever is let go and a page that leaves lose their restrictions by themselves, on the last day: the person leaves the fixed team (the rest of the team stays), assistant only, banned and split close, and the lists drop whoever left and the page that left. It runs at the end of a page exit and before each Generate. Someone who moved to leadership does not count as let go.'],
    ]],
    'lideranca' => ['Liderança', 'Leadership', [
        ['O OS segue o 5x2 de 21 dias do núcleo dele, com um grupo fixo de SRs. OC e OM, desde 07/12: ciclo de 3 semanas (uma com o fim de semana inteiro de folga, uma com sábado + 1 dia útil, uma com domingo + 1 dia útil); os 3 de cada grupo ficam em semanas diferentes, então todo dia de fim de semana tem 1 OC em cada turno e 1 OM, e os dias úteis têm 2 ou 3. Os OC dos 3 turnos de uma unidade também ficam em semanas diferentes: em cada dia de fim de semana a unidade tem o OC de 1 turno, e os outros 2 turnos ficam com o OC de outra unidade. Par da liderança que não pode folgar junto (parâmetro v4_lideranca_nao_folgam_juntos): quando os dois folgariam no mesmo dia, o OS trabalha nesse dia e folga em outro dia da mesma semana, com o grupo de OS mantendo 2 no turno. OA têm semana fixa, com o turno de cada dia.', 'The OS follows their core\'s 21-day 5x2, with a fixed group of SRs. OCs and OMs, since Dec 7: a 3-week cycle (one week with the whole weekend off, one with Saturday + 1 weekday, one with Sunday + 1 weekday); the 3 of each group are in different weeks, so every weekend day has 1 OC in each shift and 1 OM, and weekdays have 2 or 3. The OCs of a unit\'s 3 shifts are also in different weeks: on each weekend day the unit has the OC of 1 shift, and the other 2 shifts are covered by the OC of another unit. Leadership pairs who cannot be off together (parameter v4_lideranca_nao_folgam_juntos): when both would be off on the same day, the OS works that day and takes another day off in the same week, keeping 2 OSs in the shift. OAs have a fixed week, with the shift of each day.'],
        ['Na página 5C Schedule, o sufixo diz o que a pessoa faz: -2 buffer, -4 trainee (New Hire), -5 overlap, -6 OA, -7 OC, -8 OS.', 'On the 5C Schedule page, the suffix says what the person does: -2 buffer, -4 trainee (New Hire), -5 overlap, -6 OA, -7 OC, -8 OS.'],
        ['Troca de cargo (Roster da liderança): quem entra sai do núcleo de SR; quem sai fica com o lugar de quem entrou (núcleo e vagas fixas), vira SR no mesmo núcleo (OS) ou fica sem núcleo.', 'Role change (Leadership roster): the newcomer leaves their SR core; the person leaving takes the newcomer\'s place (core and fixed slots), becomes an SR in the same core (OS) or is left without a core.'],
    ]],
    'pedidos' => ['Pedidos das pessoas', 'People\'s requests', [
        ['Indisponibilidade: só o pedido aprovado vira folga, no próximo recálculo. Com menos de {antec} h de antecedência entra como urgente; recorrente vai até {meses} meses. Recusar pede comentário.', 'Unavailability: only an approved request becomes a day off, in the next recalculation. With less than {antec} h notice it is urgent; recurring requests go up to {meses} months. Declining needs a comment.'],
        ['Solicitações do SR (trabalhar como assistente ou em dupla, mudar de turno, núcleo ou unidade): o líder registra, o Planejamento aprova e aplica uma troca 1 por 1 com outro SR a partir de uma data. Ninguém fica sem vaga e nenhum posto fica sem dono; quem pediu o contrário aparece primeiro como par.', 'SR requests (work as an assistant or in a pair, change shift, core or unit): the leader records it, Planning approves it and applies a one-for-one swap with another SR from a date. No one is left without a slot and no post without an owner; those who asked for the opposite show up first as partners.'],
        ['Assistente e dupla dizem onde a pessoa fica fixa (núcleo: unidade, turno e OS) e, se souber, com quem (o titular que vai assistir ou o par). O par da troca vem desse lugar, primeiro quem já trabalha nas páginas dessa pessoa.', 'Assistant and pair requests say where the person is fixed (core: unit, shift and OS) and, if known, with whom (the owner to assist or the partner). The swap partner comes from that place, first whoever already works the pages of that person.'],
        ['Horas extras: o sistema confere {h12} h seguidas e {h52} h na semana antes de alocar.', 'Overtime: the system checks {h12} h in a row and {h52} h a week before allocating.'],
        ['Hora extra em turno com indisponibilidade aprovada pede "alocar mesmo assim". Folga não bloqueia: é o caso normal de hora extra.', 'Overtime in a shift with approved unavailability requires "allocate anyway". A day off does not block: it is the usual case for overtime.'],
    ]],
    'paginas' => ['Páginas: entrada, saída e destino', 'Pages: entry, exit and destination', [
        ['Página nova (Funil): o sistema indica 3 destinos, um por unidade, por uma nota de 0 a 100: Capacity da unidade e do turno depois de entrar a página (35), KPI da equipe (25; 35 em tier alto, 15 em tier baixo), carga do núcleo (20), afinidade com a modelo (20) e, com esses a 80%, equilíbrio das unidades (20: faturamento de 30 dias abaixo da média no turno principal ganha).', 'New page (Funnel): the system suggests 3 destinations, one per unit, by a 0–100 score: unit and shift Capacity after the page joins (35), team KPI (25; 35 for high tiers, 15 for low tiers), core load (20), model affinity (20) and, with those at 80%, unit balance (20: 30-day revenue below average on the main shift wins).'],
        ['Equilíbrio das unidades: o mesmo faturamento total de 30 dias em cada unidade e em cada coordenador (unidade × turno); o faturamento por SR fica para acompanhar. A troca de unidade leva todas as páginas da mesma modelo e só vale depois de 28 dias na unidade; o planejador decide cada troca. Não há mais divisão dos OS por faturamento (OS1, OS2 e OS3; desde 26/11): cada OS tem um grupo fixo de SRs e as páginas seguem os SRs.', 'Unit balance: the same total 30-day revenue in each unit and under each coordinator (unit × shift); revenue per SR is shown for follow-up. A unit move takes all pages of the same model and is only allowed after 28 days in the unit; the planner decides each move. There is no longer an OS split by revenue (OS1, OS2 and OS3; since Nov 26): each OS has a fixed group of SRs and pages follow the SRs.'],
        ['Página que entra no lugar de uma que saiu (na prévia da saída): entra na mesma carteira e nos mesmos núcleos; quem perdeu a vaga fixa passa para ela a partir da data de entrada. Nos dias até lá, quem fica sem página vira buffer (-2) se o Capacity diz que falta gente no turno da unidade; se não falta, sai da escala nesses dias (dá para trocar pessoa a pessoa).', 'Page coming in instead of one that left (in the exit preview): it joins the same portfolio and cores; whoever lost their fixed slot moves to it from the entry date. On the days until then, whoever is left without a page becomes buffer (-2) if Capacity says the unit\'s shift is short of people; if not, they leave the schedule on those days (can be changed person by person).'],
        ['Saída de página: prévia antes; aplicar fecha a página no Capacity, recalcula, fecha ou refaz os postos e passa quem ficou sem vaga para uma vaga sem ninguém do núcleo. Página que o Capacity já desativou só ajusta a escala.', 'Page exit: preview first; applying closes the page in Capacity, recalculates, closes or rebuilds posts and moves whoever lost a slot to an empty slot in the core. A page Capacity already deactivated only adjusts the schedule.'],
    ]],
    'kpi' => ['KPI dos SRs', 'SR KPI', [
        ['Score = Kinetic × Process × Integrity, de 0% a 120%, nas últimas 4 semanas fechadas (segunda a domingo) com pesos 4 (a última fechada), 3, 2 e 1; a semana em andamento não entra e semana sem dado fica fora da média. Kinetic: soma do peso × realizado ÷ soma do peso × meta (semana com meta pequena pesa menos; a meta da página vai para o SR pela fatia de mensagens e o realizado pela venda própria: venda direta e tip, sem assinatura, live tip, live, recurring e post), em rampa pelos pontos do documento (50% → 50%, 75% → 75%, 90% → 90%, 100% → 100%, 150% → 110%, 200% → 120%), em linha reta entre eles; mínimo 25%, máximo 120%. Novato, com menos de 2 semanas fechadas com meta, fica com 75% provisório.', 'Score = Kinetic × Process × Integrity, from 0% to 120%, over the last 4 closed weeks (Monday to Sunday) weighted 4 (the last closed one), 3, 2 and 1; the current week does not count and a week with no data is left out. Kinetic: sum of weight × actual ÷ sum of weight × goal (a week with a small goal weighs less; the page goal goes to the SR by share of messages and the actual by own sales: direct sales and tips, without subscriptions, live tips, live, recurring and posts), on a ramp through the document points (50% → 50%, 75% → 75%, 90% → 90%, 100% → 100%, 150% → 110%, 200% → 120%), in a straight line between them; minimum 25%, maximum 120%. A new hire with fewer than 2 closed weeks with a goal gets a provisional 75%.'],
        ['Process: 100% menos SLA 15 (−4%), SLA 10 (−2%) e SLA 5 (−1%) a cada 10% abaixo de 95%, 90% e 80%, proporcional; piso de 60%; hora overloaded (o SR passou de 42 fãs/h, 120% dos 35 estimados por SR, somando todas as páginas) fica fora do SLA. Integrity: 100% menos 15% por dia de falta e menos a quebra de P&G (avaliação de qualidade com Model Best Practices Não Conforme: −10% com nota 80, até −30% com nota 0; sem peso até 03/01/2027, pela data do contato); pode zerar. A ação de correção das faixas abaixo de 75% vale só para os 20% de menor score (Pareto).', 'Process: 100% minus SLA 15 (−4%), SLA 10 (−2%) and SLA 5 (−1%) for every 10% below 95%, 90% and 80%, pro rata; 60% floor; an overloaded hour (the SR went above 42 fans/h, 120% of the 35 estimated per SR, adding up all pages) is left out of the SLA. Integrity: 100% minus 15% per day absent and minus P&G breaches (quality evaluation with Model Best Practices non-compliant: −10% at score 80, up to −30% at score 0; no weight up to 03/01/2027, by the contact date); it can reach zero. The corrective action of the bands below 75% applies only to the 20% with the lowest score (Pareto).'],
        ['Na escala (o KPI é o indicador oficial): nível 4 = 120%; 3 = 100% a 119% (só perde o posto para o 4); 2 = mantém (75% a 99%, novato e quem está fora dos 20% piores); 1 = entre os 20% piores com 50% a 74% (perde o posto para 3 ou 4); 0 = entre os 20% piores abaixo de 50% (fora das páginas prioritárias, último no acúmulo e na sobrecarga; abaixo de 25%, só cobertura). No Gerar, quem bateu 65% da meta na página vem primeiro, depois o nível, o score e o tempo de casa; no máximo 20% dos SRs mudam de posto pelo KPI na semana. O new hire (SR nível 0 do cargo) segue a rampa, contada do primeiro cadastro de SR: 1ª semana assistente ou buffer (cobrindo página, só até o Tier F, US$ 16 mil em 30 dias); 2ª, regular até o Tier F; 3ª e 4ª, regular até o Tier E (US$ 32 mil); até a 4ª, assistente ou buffer têm preferência; depois, regular até o Tier E. De assistente, qualquer página; se o titular falta, o new hire que está de assistente não vira regular (a vaga do titular fica em aberto). Mass por turno, "não seguir o plano", DNR e multas ainda não têm dado.', 'In the schedule (the KPI is the official indicator): level 4 = 120%; 3 = 100% to 119% (only loses the post to a 4); 2 = keeps (75% to 99%, new hires and those outside the worst 20%); 1 = among the worst 20% with 50% to 74% (loses the post to a 3 or 4); 0 = among the worst 20% below 50% (off priority pages, last for stacking and overload; below 25%, cover only). In Generate, whoever hit 65% of the page goal comes first, then the level, the score and tenure; at most 20% of SRs change post because of the KPI in a week. A new hire (SR level 0 by role) follows the ramp, counted from the first SR record: 1st week assistant or buffer (covering a page, only up to Tier F, US$ 16k in 30 days); 2nd, regular up to Tier F; 3rd and 4th, regular up to Tier E (US$ 32k); up to the 4th, assistant or buffer are preferred; after that, regular up to Tier E. As an assistant, any page; if the main SR is missing, a new hire who is the assistant does not become the regular (the slot of the main SR stays open). Mass per shift, "not following the plan", DNR and fines have no data yet.'],
    ]],
    'quadro' => ['Quadro e contratação', 'Headcount and hiring', [
        ['Capacity: precisa = titulares (postos × {fator}) + buffer, por unidade e turno; tem = os SRs com cadastro no 5C Escalas (desde 09/11; antes, a foto de 27/10), guardados dia a dia no registro do quadro desde 01/11; falta = precisa − tem. O absenteísmo do buffer conta de 01/11 em diante, com o D na média de A e C enquanto o registro de faltas do D é conferido. A tela mostra uma versão por dia. O Capacity não entra no corte de 01/11.', 'Capacity: needs = main SRs (posts × {fator}) + buffer, per unit and shift; has = the SRs with a record in 5C Escalas (since 11/09; before that, the 10/27 snapshot), kept day by day in the headcount record since 11/01; shortfall = needs − has. Buffer absenteeism counts from 11/01 on, with D at the average of A and C while the D absence records are checked. The screen shows one version per day. Capacity is not affected by the 11/01 cutoff.'],
        ['Ocupação dos postos: SRs escalados por dia nas páginas da carteira ÷ postos do Capacity × dias da semana; buffer, Overlap, treinamento e liderança não contam. Lacuna = bloco de 4 h sem ninguém.', 'Post occupancy: SRs scheduled per day on the portfolio\'s pages ÷ Capacity posts × days of the week; buffer, Overlap, training and leadership do not count. Gap = a 4-hour block with no one.'],
        ['Requisição de vagas: o plano de turmas é o do Capacity (fc_contratacoes, até {teto_turno} por turno em cada turma). A requisição abre até 14 dias antes do início da turma; etapas: planejada → aberta → contratada → em treinamento → operando. A simulação usa a saída semanal de cada turno, a saída do novato (12% em 30 dias e mais 11% até 90, sem contar duas vezes) e o novato a 50% nos primeiros 30 dias; "Sugerir tamanhos" só refaz as turmas planejadas.', 'Job requisitions: the class plan is the Capacity one (fc_contratacoes, up to {teto_turno} per shift in each class). The requisition opens up to 14 days before the class starts; stages: planned → open → hired → in training → operating. The simulation uses each shift\'s weekly exit rate, new hire exits (12% in 30 days and 11% more up to 90, not counted twice) and new hires at 50% in the first 30 days; "Suggest sizes" only redoes the planned classes.'],
        ['Destino do novato: no turno da turma, uma pessoa por vez vai para a unidade com mais lacunas na escala da semana em que a turma fica disponível (no empate, a com mais falta no Capacity, contando os novatos já designados); cada pessoa desconta {blocos_sr} blocos de lacuna. Dentro da unidade, o núcleo com menos SRs para a parte dele (postos ÷ 2). É sugestão: o WFM confirma, e só o cadastro em Colaboradores põe a pessoa na escala. Não mexe nas regras P-01 a P-04 nem nas restrições dos OM.', 'New hire destination: in the class shift, one person at a time goes to the unit with the most gaps in the schedule of the week the class becomes available (on a tie, the one with the largest Capacity shortfall, counting new hires already assigned); each person takes off {blocos_sr} gap blocks. Within the unit, the core with the fewest SRs for its share (posts ÷ 2). It is a suggestion: WFM confirms, and only the record in Employees puts the person on the schedule. It does not change rules P-01 to P-04 or the OM restrictions.'],
        ['Plano de turmas: qualquer turma pode ser incluída (também entre as do plano), mudada ou apagada pelo perfil de planejar. Turma com requisição aberta ou contratada muda no acompanhamento; em treinamento ou operando não muda. Abrir a requisição confirma a turma no plano do Capacity. Turma apagada fica cancelada no plano.', 'Class plan: any class can be added (also between existing ones), changed or deleted with the planning profile. A class with an open or hired requisition changes under tracking; in training or operating it does not change. Opening the requisition confirms the class in the Capacity plan. A deleted class stays cancelled in the plan.'],
        ['Fora das unidades: SRs do RH sem unidade no 5C Escalas (liderança e trainees ficam de fora) recebem a sugestão de unidade, turno e núcleo pela mesma regra do destino do novato, mantendo o turno da pessoa quando ele é conhecido. Quem já saiu pelo Escalas e o RH ainda lista aparece à parte, para avisar o RH.', 'Outside the units: HR SRs with no unit in 5C Escalas (leadership and trainees are left out) get a suggested unit, shift and core by the same rule as the new hire destination, keeping the person\'s shift when it is known. Those who already left in Escalas but HR still lists appear separately, to tell HR.'],
    ]],
    'treinamento' => ['Treinamento de New Hires', 'New Hire training', [
        ['O e-mail do Treinamento é colado em Quadro e contratação › Turmas de treinamento: o sistema lê turmas, horário, datas, nesting, páginas pedidas e trainees, e avisa o que não bate (turno × horário, datas, lista de contratados).', 'The Training e-mail is pasted in People › Training: the system reads classes, hours, dates, nesting, requested pages and trainees, and flags what does not match (shift × hours, dates, hire list).'],
        ['Páginas emprestadas: a menor de um posto com 2 ou mais páginas, as mesmas no ciclo de 2 semanas, nunca OFTV, sem mês abaixo de {trn_min}, sem prioridade fixa e sem repetir entre turnos ao mesmo tempo. Até 4 trainees por página, de 5 a 8 em 2, 9 ou mais em 3. O dono do turno continua dono e com a comissão; nas pausas do treinamento ele assume.', 'Lent pages: the smallest page of a post with 2 or more pages, the same for the 2-week cycle, never OFTV, no month below {trn_min}, no fixed priority and no repeats across shifts at the same time. Up to 4 trainees per page, 5 to 8 in 2, 9 or more in 3. The shift owner stays the owner and keeps the commission; during training breaks they take over.'],
        ['Turma confirmada: os trainees vão para a página 5C Schedule com -4, de segunda a sexta, no horário da turma. Até o dia disponível para a operação ficam fora da escala normal, mesmo com cadastro.', 'Confirmed class: trainees go on the 5C Schedule page with -4, Monday to Friday, in the class hours. Until the day available for operation they stay out of the regular schedule, even with a record.'],
    ]],
    'politica' => ['Política de páginas', 'Page policy', [
        ['Atingimento = 5CReps realizado ÷ meta 5CReps (Intraday). Medido para a página na unidade (todos os turnos, desde que entrou na unidade) e para a página em cada turno (desde que o owner atual assumiu). Janela de {jan} dias; são precisos {dmin} dias com dados.', 'Attainment = 5CReps actual ÷ 5CReps target (Intraday). Measured for the page in the unit (all shifts, since it joined the unit) and for the page in each shift (since the current owner took over). {jan}-day window; {dmin} days of data are needed.'],
        ['Abaixo de {corte} o prazo corre, com retorno decrescente: prazo = {pmin} + ({pmax} − {pmin}) × ((atingimento − {piso}) ÷ ({corte} − {piso}))^{gamma}. Igual ou abaixo de {piso}: {pmin} dias. Hoje: {prazos}.', 'Below {corte} the deadline runs, with diminishing returns: deadline = {pmin} + ({pmax} − {pmin}) × ((attainment − {piso}) ÷ ({corte} − {piso}))^{gamma}. At or below {piso}: {pmin} days. Today: {prazos}.'],
        ['Entre {corte} e a meta: acompanhamento por {acomp} dias antes de sugerir troca. Na meta: mantém. {dest} ou mais por {destd} dias: destaque (candidata a página maior).', 'Between {corte} and target: monitoring for {acomp} days before suggesting a swap. On target: keeps the page. {dest} or more for {destd} days: highlight (candidate for a bigger page).'],
        ['Prazo vencido só no turno: troca de owner dentro do núcleo dono (o melhor KPI entra e troca de vaga com quem sai), depois de pelo menos {omin} dias do owner na página. Prazo vencido na unidade: troca de unidade, com prévia; o Capacity só muda depois da confirmação.', 'Deadline missed only in the shift: owner change within the owning core (best KPI comes in and swaps slots with the person leaving), after at least {omin} days of the owner on the page. Deadline missed in the unit: unit change, with a preview; Capacity only changes after confirmation.'],
        ['Estabilidade: {car} dias sem reavaliar depois de uma troca; no máximo {maxs} páginas por unidade por semana. Descartar uma sugestão a esconde por 7 dias.', 'Stability: {car} days without re-evaluating after a swap; at most {maxs} pages per unit per week. Dismissing a suggestion hides it for 7 days.'],
        ['Prioridades fixas (vencem a nota): {prio}.', 'Fixed priorities (override the score): {prio}.'],
    ]],
];
// Política de páginas e KPI individual: só WFM/Planejamento e Admin. O Mérito é Legacy (1.38.0) e não está nas Regras.
if (!escPodeVerRestrito()) {
    unset($R['politica'], $R['kpi']);
}
?>
